# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: intake
def intake(xs, offset=-1):
    return [v + offset for v in xs[1:]]

# region: shape
def shape(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: digest
def digest(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(shape(intake(fold(gather(sift(raw))))))

